'use strict';

// JCS（RFC 8785 JSON Canonicalization Scheme）完整兼容实现。
// 与参考实现 canonicalize（Apache-2.0）行为一致：对象键按 UTF-16 code unit 排序、
// 数字/字符串沿用 ECMAScript JSON.stringify 的序列化、数组保持顺序、拒绝 NaN/Infinity。
// 禁止用普通 JSON.stringify 冒充 JCS（普通 stringify 不排序对象键）。

function canonicalizeValue(value, seen) {
  if (typeof value === 'number') {
    if (Number.isNaN(value) || !Number.isFinite(value)) {
      throw new TypeError('canonicalizeJson: NaN 或 Infinity 不允许');
    }
    return JSON.stringify(value);
  }

  if (value === null || typeof value !== 'object') {
    return JSON.stringify(value);
  }

  if (typeof value.toJSON === 'function') {
    if (seen.has(value)) {
      throw new TypeError('canonicalizeJson: 检测到循环引用');
    }
    seen.add(value);
    const result = canonicalizeValue(value.toJSON(), seen);
    seen.delete(value);
    return result;
  }

  if (seen.has(value)) {
    throw new TypeError('canonicalizeJson: 检测到循环引用');
  }
  seen.add(value);

  let result;
  if (Array.isArray(value)) {
    const values = value.map(item => {
      const v = item === undefined || typeof item === 'symbol' ? null : item;
      return canonicalizeValue(v, seen);
    });
    result = `[${values.join(',')}]`;
  } else {
    const parts = [];
    // Object.keys 返回顺序已按整数键 + 插入顺序；sort() 按 UTF-16 code unit 升序，符合 RFC 8785。
    for (const key of Object.keys(value).sort()) {
      const v = value[key];
      if (v === undefined || typeof v === 'symbol') continue;
      parts.push(`${canonicalizeValue(key, seen)}:${canonicalizeValue(v, seen)}`);
    }
    result = `{${parts.join(',')}}`;
  }

  seen.delete(value);
  return result;
}

function canonicalizeJson(value) {
  if (value === undefined) {
    throw new TypeError('canonicalizeJson: 无法规范化 undefined');
  }
  return canonicalizeValue(value, new Set());
}

module.exports = { canonicalizeJson };
